(() => {
  const hdr = document.querySelector('.site-header');
  const hero = document.querySelector('.hero');
  const bar = document.querySelector('.specbar');
  const r = el => el ? Math.round(el.getBoundingClientRect().height) : 0;
  const barRect = bar.getBoundingClientRect();
  return {
    vh: window.innerHeight,
    header: r(hdr), hero: r(hero), bar: r(bar),
    total: r(hdr) + r(hero) + r(bar),
    barBottom: Math.round(barRect.bottom),
    barFullyVisible: barRect.bottom <= window.innerHeight + 1,
    cssVar: getComputedStyle(document.documentElement).getPropertyValue('--specbar-h').trim(),
    cols: getComputedStyle(document.querySelector('.specbar__inner')).gridTemplateColumns.split(' ').length
  };
})()
